def compute(vars):
    restructuring_2018 = vars["v1"]
    restructuring_2019 = vars["v2"]
    average = (restructuring_2018 + restructuring_2019) / 2

    return {
        "value": average,
        "trace": {
            "restructuring_2018": restructuring_2018,
            "restructuring_2019": restructuring_2019,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
